import{_ as e,c as a,o as t,a3 as s}from"./chunks/framework.C5U8cnJv.js";const l="/xhh-blog/assets/ccswitch.BQpEYL3d.png",c="/xhh-blog/assets/img_model.D9c4OQVC.png",d="/xhh-blog/assets/ccswitch-model.5l1uqQMl.png",i="/xhh-blog/assets/img_claude.Df4eLHzD.png",o="/xhh-blog/assets/claude-skills.CEyelBZ1.png",p="/xhh-blog/assets/image-2.Du-RAtSE.png",x=JSON.parse('{"title":"Claude Code","description":"","frontmatter":{},"headers":[],"relativePath":"ai/claudecode.md","filePath":"ai/claudecode.md"}'),n={name:"ai/claudecode.md"},r=s(`<h1 id="claude-code" tabindex="-1"><a href="https://www.runoob.com/claude-code/claude-code-tutorial.html" target="_blank" rel="noreferrer">Claude Code</a> <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;[Claude Code](https://www.runoob.com/claude-code/claude-code-tutorial.html)&quot;">​</a></h1><h2 id="安装-claude-code" tabindex="-1">安装 claude code <a class="header-anchor" href="#安装-claude-code" aria-label="Permalink to &quot;安装 claude code&quot;">​</a></h2><h3 id="mac-homebrew-安装-claude-code" tabindex="-1">Mac Homebrew 安装 claude code <a class="header-anchor" href="#mac-homebrew-安装-claude-code" aria-label="Permalink to &quot;Mac Homebrew 安装 claude code&quot;">​</a></h3><p>在终端输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brew install --cask claude-code</span></span></code></pre></div><h3 id="查看-claude-code-版本" tabindex="-1">查看 claude code 版本 <a class="header-anchor" href="#查看-claude-code-版本" aria-label="Permalink to &quot;查看 claude code 版本&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude --version</span></span></code></pre></div><h3 id="安装-cc-switch" tabindex="-1">安装 CC Switch <a class="header-anchor" href="#安装-cc-switch" aria-label="Permalink to &quot;安装 CC Switch&quot;">​</a></h3><p>CC‑Switch 为社区第三方工具，非 Anthropic 官方，用于切换第三方模型供应商</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brew tap farion1231/ccswitch</span></span>
<span class="line"><span></span></span>
<span class="line"><span>brew install --cask cc-switch</span></span></code></pre></div><h2 id="接入国产大模型" tabindex="-1">接入国产大模型 <a class="header-anchor" href="#接入国产大模型" aria-label="Permalink to &quot;接入国产大模型&quot;">​</a></h2><h3 id="接入-deepseek-大模型" tabindex="-1">接入 DeepSeek 大模型 <a class="header-anchor" href="#接入-deepseek-大模型" aria-label="Permalink to &quot;接入 DeepSeek 大模型&quot;">​</a></h3><p>获取 DeepSeek API key:</p><p><a href="https://platform.deepseek.com/api_keys" target="_blank" rel="noreferrer">https://platform.deepseek.com/api_keys</a></p><p>打开 cc switch，添加新供应商，选择 DeepSeek，输入 API key，点添加即可。</p><p><img src="`+l+'" alt="alt text"></p><h3 id="接入千问大模型" tabindex="-1">接入千问大模型 <a class="header-anchor" href="#接入千问大模型" aria-label="Permalink to &quot;接入千问大模型&quot;">​</a></h3><p><img src="'+c+'" alt="alt text"></p><p><img src="'+d+'" alt="alt text"></p><p>注意：免费额度用完会自动扣费，先在后台设置用完即停。</p><h2 id="claude-code-使用" tabindex="-1">claude code 使用 <a class="header-anchor" href="#claude-code-使用" aria-label="Permalink to &quot;claude code 使用&quot;">​</a></h2><p>在终端输入 claude，回车启动；</p><p>第一次使用，会有一些初始化设置，比如颜色模式等，选中回车。后续可以输入 /theme 修改。</p><p><img src="'+i+'" alt="alt text"></p><h3 id="切换模型" tabindex="-1">切换模型 <a class="header-anchor" href="#切换模型" aria-label="Permalink to &quot;切换模型&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/model</span></span></code></pre></div><p>重要区分：原生 <code>/model</code> 和 cc-switch <code>/model</code></p><p>1.<strong>未安装 cc-switch</strong>：<code>/model</code> 是 Claude Code <strong>官方原生内置命令</strong>，仅用于切换 Anthropic 官方 Claude 系列模型（Opus / Sonnet / Haiku）。</p><p>2.<strong>安装 cc-switch 之后</strong>：cc-switch 会<strong>劫持覆盖 <code>/model</code> 命令</strong>，此时 <code>/model</code> 变成 cc-switch 的模型选择器，可以切换 DeepSeek、通义千问等第三方 OpenAI 兼容模型。</p><blockquote><p>如果需要原生 <code>/model</code> 能力，需要移除 cc-switch。</p></blockquote><p><a href="https://code.claude.com/docs/zh-CN/model-config#setting-your-model" target="_blank" rel="noreferrer">https://code.claude.com/docs/zh-CN/model-config#setting-your-model</a></p><h3 id="退出-claude-code" tabindex="-1">退出 claude code <a class="header-anchor" href="#退出-claude-code" aria-label="Permalink to &quot;退出 claude code&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/exit</span></span></code></pre></div><h3 id="手动更新-claude-code" tabindex="-1">手动更新 claude-code <a class="header-anchor" href="#手动更新-claude-code" aria-label="Permalink to &quot;手动更新 claude-code&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brew upgrade claude-code</span></span></code></pre></div><h3 id="卸载-claude-code" tabindex="-1">卸载 claude code <a class="header-anchor" href="#卸载-claude-code" aria-label="Permalink to &quot;卸载 claude code&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brew uninstall --cask claude-code</span></span></code></pre></div><h2 id="plugin-和-skills" tabindex="-1">plugin 和 skills <a class="header-anchor" href="#plugin-和-skills" aria-label="Permalink to &quot;plugin 和 skills&quot;">​</a></h2><p>1.注册插件市场源，把 <a href="https://github.com/anthropics/skills" target="_blank" rel="noreferrer">github.com/anthropics/skills</a> 仓库添加到插件市场列表：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin marketplace add anthropics/skills</span></span></code></pre></div><p>2.然后安装插件包(example-skills包含12个skill)：</p><p>/plugin =&gt; Marketplaces =&gt; 选中 anthropic-agent-skills =&gt; Browse plugins =&gt; Discover =&gt; example skills</p><p>或</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin install example-skills@anthropic-agent-skills</span></span></code></pre></div><p>3.查看插件（包括 plugins 包内 skill 和 <code>~/.claude/skills</code> 内的 skill）：</p><p><code>/skills</code></p><hr><p>Anthropic Skills 文档：<a href="https://anthropics-skills.mintlify.app/installation?f_link_type=f_linkinlinenote&amp;flow_extra=eyJpbmxpbmVfZGlzcGxheV9wb3NpdGlvbiI6MCwiZG9jX3Bvc2l0aW9uIjowLCJkb2NfaWQiOiI5NDU1OWJkMDM4Mzc1NGU1LTVhMDEzODdjNzU1NTQwYjAifQ%3D%3D" target="_blank" rel="noreferrer">https://anthropics-skills.mintlify.app/installation?f_link_type=f_linkinlinenote&amp;flow_extra=eyJpbmxpbmVfZGlzcGxheV9wb3NpdGlvbiI6MCwiZG9jX3Bvc2l0aW9uIjowLCJkb2NfaWQiOiI5NDU1OWJkMDM4Mzc1NGU1LTVhMDEzODdjNzU1NTQwYjAifQ%3D%3D</a></p><hr><p>skills 使用示例： <img src="'+o+'" alt="alt text"></p><hr><table tabindex="0"><thead><tr><th>对比</th><th>Marketplace 插件包 /plugin install</th><th>手动部署 Skill 放入 skills 目录</th></tr></thead><tbody><tr><td>存储目录</td><td><code>~/.claude/plugins/</code></td><td><code>~/.claude/skills/</code></td></tr><tr><td>最小安装单元</td><td>整个插件包，一次性安装包内全部技能</td><td>单个 Skill，按需单独放置</td></tr><tr><td>管理器</td><td><code>/plugin</code> 面板管理</td><td>无插件管理器，手动管理文件夹</td></tr><tr><td>自动更新</td><td>支持 marketplace 更新</td><td>❌ 不支持，手动替换文件</td></tr><tr><td>卸载方式</td><td><code>/plugin uninstall</code></td><td>直接删除对应文件夹</td></tr><tr><td>刷新技能列表</td><td><code>/reload-plugins [--force]</code></td><td><code>/reload-skills</code></td></tr></tbody></table><h2 id="连接-figma-mcp" tabindex="-1">连接 Figma MCP <a class="header-anchor" href="#连接-figma-mcp" aria-label="Permalink to &quot;连接 Figma MCP&quot;">​</a></h2><p>打开 Figma 官网文档，先安装 MCP：</p><p><a href="https://developers.figma.com/docs/figma-mcp-server/remote-server-installation/#claude-code" target="_blank" rel="noreferrer">https://developers.figma.com/docs/figma-mcp-server/remote-server-installation/#claude-code</a></p><p><img src="'+p+'" alt="alt text"></p><p>在终端输入</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude mcp add --scope user --transport http figma https://mcp.figma.com/mcp</span></span></code></pre></div><p>启动 claude，输入 /mcp，选择 figma，点击 ‌Authenticate，授权访问。</p><p>列出所有已配置的服务器</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude mcp list</span></span></code></pre></div>',61),h=[r];function u(g,m,b,k,v,f){return t(),a("div",null,h)}const C=e(n,[["render",u]]);export{x as __pageData,C as default};
